/*
 * A142652  Primes congruent to 27 mod 56.
 * https://oeis.org/A142652
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 224, u32 n <= 246, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   ensure_capacity, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Primes congruent to 27 modulo 56, generated by simple trial division */

#include <stddef.h>
#include <stdlib.h>
#include "../utils/is_prime_big.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n)
{
    static seq_t *primes = NULL;
    static size_t primes_len = 0;
    static size_t primes_cap = 0;
    static idx_t next_k = 0;

    while (primes_len < n) {
        seq_t cand = (seq_t)56 * next_k + 27;
        if (is_prime_big(cand)) {
            ensure_capacity(primes_len + 1, &primes_cap, (void **)&primes, sizeof(seq_t));
            primes[primes_len++] = cand;
        }
        ++next_k;
    }
    return primes[n - 1];
}
